import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from stackedHorizontal ----
// US Census American Community Survey population by state and age, the 20 most
// populous states, with the survey's nine age columns collapsed into five bands.
const AGE_GROUPS = ['Under 20', '20 to 39', '40 to 59', '60 to 79', '80 and over'];

type StateAgeRow = { state: string; values: number[] };

const statePopulationByAge: StateAgeRow[] = [
  { state: 'California', values: [10208774, 11163567, 10221352, 5749139, 1311374] },
  { state: 'Texas', values: [7893619, 7716981, 6890676, 3722980, 732179] },
  { state: 'Florida', values: [4542114, 5014006, 5338559, 4020206, 1019566] },
  { state: 'New York', values: [4765536, 5499621, 5372947, 3255262, 804091] },
  { state: 'Illinois', values: [3335666, 3511693, 3470435, 2054942, 478948] },
  { state: 'Pennsylvania', values: [3066949, 3232857, 3526669, 2342433, 615069] },
  { state: 'Ohio', values: [2953102, 2934262, 3168753, 2048934, 481890] },
  { state: 'Georgia', values: [2785188, 2775906, 2742683, 1526361, 269182] },
  { state: 'North Carolina', values: [2560696, 2619218, 2713863, 1704554, 342497] },
  { state: 'Michigan', values: [2505495, 2500365, 2737584, 1767853, 398303] },
  { state: 'New Jersey', values: [2232761, 2283379, 2561865, 1470019, 367432] },
  { state: 'Virginia', values: [2099090, 2282745, 2296956, 1356904, 274606] },
  { state: 'Washington', values: [1778602, 1975041, 1891612, 1185302, 242589] },
  { state: 'Arizona', values: [1804818, 1796858, 1668148, 1204037, 254716] },
  { state: 'Massachusetts', values: [1600119, 1818646, 1895234, 1139736, 288408] },
  { state: 'Indiana', values: [1768623, 1732676, 1755837, 1089311, 243131] },
  { state: 'Tennessee', values: [1661277, 1732650, 1770615, 1155984, 227483] },
  { state: 'Missouri', values: [1556883, 1594727, 1608523, 1056964, 242554] },
  { state: 'Maryland', values: [1506682, 1599443, 1678653, 967045, 208079] },
  { state: 'Wisconsin', values: [1460872, 1475440, 1580952, 995787, 241747] }
];

// Left margin is sized to the longest state name so no category label is clipped.
const MARGIN = { top: 34, right: 48, bottom: 34, left: 100 };
const LEGEND_SWATCH = 11;
const MIN_LEGEND_ITEM = 88;
const MIN_TOTAL_ROW_HEIGHT = 13;

const formatTick = d3.format('~s');
const formatValue = d3.format(',');

/** One row per state whose `values` line up, in order, with the `ageGroups` they stack. */
export type Data = {
  ageGroups: string[];
  rows: { state: string; values: number[] }[];
};

const DEMO: Data = { ageGroups: AGE_GROUPS, rows: statePopulationByAge };

export default function StackedHorizontalBar({
  data = DEMO,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.78);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const color = useMemo(
    () =>
      d3
        .scaleOrdinal<string, string>()
        .domain(data.ageGroups)
        .range(d3.schemeObservable10)
        .unknown('var(--muted)'),
    [data]
  );

  const rows = useMemo(
    () =>
      data.rows
        .map((d) => ({ ...d, total: d3.sum(d.values) }))
        .sort((a, b) => b.total - a.total),
    [data]
  );

  const series = useMemo(
    () =>
      d3
        .stack<StateAgeRow, string>()
        .keys(data.ageGroups)
        .value((d, key) => d.values[data.ageGroups.indexOf(key)] ?? 0)(rows),
    [data, rows]
  );

  const x = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(rows, (d) => d.total) ?? 0])
        .nice()
        .range([0, Math.max(innerWidth, 0)]),
    [rows, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleBand<string>()
        .domain(rows.map((d) => d.state))
        .range([0, Math.max(innerHeight, 0)])
        .padding(0.18),
    [rows, innerHeight]
  );

  const xTicks: Tick[] = useMemo(
    () =>
      x
        .ticks(Math.max(2, Math.round(innerWidth / 90)))
        .map((v) => ({ value: formatTick(v), offset: x(v) })),
    [x, innerWidth]
  );

  if (width === 0) return null;

  const bandwidth = y.bandwidth();
  const legendStep = innerWidth / data.ageGroups.length;
  const showLegend = legendStep >= MIN_LEGEND_ITEM;
  const showTotals = bandwidth >= MIN_TOTAL_ROW_HEIGHT;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={
        'Stacked horizontal bar chart of United States population by state and age band, ' +
        'from the American Community Survey. The 20 most populous states run down the left, ' +
        'sorted by total population descending, and each bar stacks five age bands from ' +
        'under 20 to 80 and over.'
      }
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis">
          {xTicks.map((t) => (
            <line
              key={t.value}
              className="grid"
              x1={t.offset}
              x2={t.offset}
              y1={0}
              y2={innerHeight}
            />
          ))}
        </g>

        {series.map((layer) => (
          <g key={layer.key} fill={color(layer.key)}>
            {layer.map((point) => {
              const top = y(point.data.state) ?? 0;
              const segmentWidth = Math.max(x(point[1]) - x(point[0]), 0);
              return (
                <rect
                  key={point.data.state}
                  x={x(point[0])}
                  y={top}
                  width={segmentWidth}
                  height={bandwidth}
                >
                  <title>{`${point.data.state} · ${layer.key}: ${formatValue(
                    point[1] - point[0]
                  )}`}</title>
                </rect>
              );
            })}
          </g>
        ))}

        {rows.map((row) => {
          const middle = (y(row.state) ?? 0) + bandwidth / 2;
          return (
            <g key={row.state}>
              <text
                x={-8}
                y={middle}
                dy="0.32em"
                textAnchor="end"
                fontSize={11}
                fill="var(--text)"
              >
                {row.state}
              </text>
              {showTotals && (
                <text
                  x={x(row.total) + 6}
                  y={middle}
                  dy="0.32em"
                  fontSize={10}
                  fill="var(--muted)"
                >
                  {formatTick(row.total)}
                </text>
              )}
            </g>
          );
        })}

        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />

        {showLegend && (
          <g transform="translate(0,-22)">
            {data.ageGroups.map((group, i) => (
              <g key={group} transform={`translate(${i * legendStep},0)`}>
                <rect width={LEGEND_SWATCH} height={LEGEND_SWATCH} fill={color(group)} />
                <text x={LEGEND_SWATCH + 5} y={LEGEND_SWATCH - 1} fontSize={11} fill="var(--text)">
                  {group}
                </text>
              </g>
            ))}
          </g>
        )}
      </g>
    </svg>
  );
}
